interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
  timezone: string;
  lastUpdated: string;
}

interface UserData {
  id: string;
  name: string;
  email: string;
  lastLogin: string;
  preferences: UserPreferences;
}

// Function to fetch fresh user data on each request
async function fetchUserData(): Promise<UserData | null> {
  try {
    // Using cache: 'no-store' ensures fresh data on each request
    const res = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL || ''}/api/user`, {
      cache: 'no-store',
      headers: {
        'Content-Type': 'application/json',
      },
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user data');
    }

    return res.json();
  } catch (error) {
    console.error('Error fetching user data:', error);
    return null;
  }
}

// Function to fetch fresh user preferences on each request
async function fetchUserPreferences(): Promise<UserPreferences | null> {
  try {
    // Using cache: 'no-store' ensures fresh data on each request
    const res = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL || ''}/api/user/preferences`, {
      cache: 'no-store',
      headers: {
        'Content-Type': 'application/json',
      },
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    return res.json();
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    return null;
  }
}

export default async function UserDashboard() {
  // Fetch fresh data on each request
  const [userData, userPreferences] = await Promise.all([
    fetchUserData(),
    fetchUserPreferences()
  ]);

  if (!userData || !userPreferences) {
    return (
      <div className="user-dashboard">
        <h2>User Dashboard</h2>
        <p>Failed to load user data. Please try again later.</p>
      </div>
    );
  }

  return (
    <div className="user-dashboard">
      <h2>User Dashboard</h2>

      <div className="user-info">
        <h3>Welcome, {userData.name}!</h3>
        <p>Email: {userData.email}</p>
        <p>Last Login: {new Date(userData.lastLogin).toLocaleString()}</p>
      </div>

      <div className="user-preferences">
        <h3>Your Current Preferences</h3>
        <div className="preference-grid">
          <div className="preference-item">
            <strong>Theme:</strong> {userPreferences.theme}
          </div>
          <div className="preference-item">
            <strong>Notifications:</strong> {userPreferences.notifications ? 'Enabled' : 'Disabled'}
          </div>
          <div className="preference-item">
            <strong>Language:</strong> {userPreferences.language}
          </div>
          <div className="preference-item">
            <strong>Timezone:</strong> {userPreferences.timezone}
          </div>
          <div className="preference-item">
            <strong>Last Updated:</strong> {new Date(userPreferences.lastUpdated).toLocaleString()}
          </div>
        </div>
      </div>

      <div className="dashboard-actions">
        <p>Your preferences are updated in real-time. Refresh the page to see new random preferences.</p>
      </div>
    </div>
  );
}

