  const [userData, userPreferences] = await Promise.all([
    fetchUserData(),
    fetchUserPreferences()
  ]);

  if (!userData || !userPreferences) {
    return (
      <div className="user-dashboard p-6 bg-gray-50 min-h-screen">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">User Dashboard</h2>
        <p className="text-red-600">Failed to load user data. Please try again later.</p>
      </div>
    );
  }

  return (
    <div className="user-dashboard p-6 bg-gray-50 min-h-screen">
      <h2 className="text-2xl font-bold text-gray-800 mb-6">User Dashboard</h2>

      <div className="user-info bg-white rounded-lg p-6 mb-6 shadow-sm">
        <h3 className="text-xl font-semibold text-gray-800 mb-4">Welcome, {userData.name}!</h3>
        <p className="text-gray-600 mb-2"><strong>Email:</strong> {userData.email}</p>
        <p className="text-gray-600"><strong>Last Login:</strong> {new Date(userData.lastLogin).toLocaleString()}</p>
      </div>

      <div className="user-preferences bg-white rounded-lg p-6 mb-6 shadow-sm">
        <h3 className="text-xl font-semibold text-gray-800 mb-4">Your Current Preferences</h3>
        <div className="preference-grid grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="preference-item bg-gray-50 p-4 rounded-lg">
            <strong className="text-gray-700">Theme:</strong> 
            <span className="ml-2 px-2 py-1 bg-blue-100 text-blue-800 text-sm font-medium rounded">
              {userPreferences.theme}
            </span>
          </div>
          <div className="preference-item bg-gray-50 p-4 rounded-lg">
            <strong className="text-gray-700">Notifications:</strong> 
            <span className="ml-2 px-2 py-1 text-sm font-medium rounded">
              {userPreferences.notifications ? (
                <span className="bg-green-100 text-green-800">Enabled</span>
              ) : (
                <span className="bg-red-100 text-red-800">Disabled</span>
              )}
            </span>
          </div>
          <div className="preference-item bg-gray-50 p-4 rounded-lg">
            <strong className="text-gray-700">Language:</strong> 
            <span className="ml-2 px-2 py-1 bg-purple-100 text-purple-800 text-sm font-medium rounded">
              {userPreferences.language}
            </span>
          </div>
          <div className="preference-item bg-gray-50 p-4 rounded-lg">
            <strong className="text-gray-700">Timezone:</strong> 
            <span className="ml-2 px-2 py-1 bg-yellow-100 text-yellow-800 text-sm font-medium rounded">
              {userPreferences.timezone}
            </span>
          </div>
          <div className="preference-item bg-gray-50 p-4 rounded-lg md:col-span-2">
            <strong className="text-gray-700">Last Updated:</strong> 
            <span className="ml-2 px-2 py-1 bg-gray-200 text-gray-800 text-sm font-medium rounded">
              {new Date(userPreferences.lastUpdated).toLocaleString()}
            </span>
          </div>
        </div>
      </div>

      <div className="dashboard-actions bg-white rounded-lg p-6 shadow-sm">
        <p className="text-gray-600">
          Your preferences are updated in real-time. Refresh the page to see new random preferences.
        </p>
      </div>
    </div>
  );
}
